<?php
require __DIR__ . '/config.php';
$settings = pmb_settings();
$lokasi = pmb_content('lokasi');
$campuses = isset($lokasi['campuses']) && is_array($lokasi['campuses']) ? $lokasi['campuses'] : array();
$tints = array('blue'=>array('tint-blue','tint-blueb'),'indigo'=>array('tint-indigo','tint-indigob'),'violet'=>array('tint-violet','tint-violetb'),'teal'=>array('tint-teal','tint-tealb'),'emerald'=>array('tint-teal','tint-tealb'));
function lokasi_h($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function lokasi_level_class($level) { $x = strtolower((string)$level); if (strpos($x,'s-2') !== false) return 'lv-s2'; if (strpos($x,'d-3') !== false) return 'lv-d3'; if (strpos($x,'terapan') !== false) return 'lv-st'; return 'lv-s1'; }
