<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{--ink:#111827;--head:#0B1220;--muted:#6B7280;--faint:#9CA3AF;--line:#EDF0F4;--accent:#2563EB;--bg:#F6F8FC;--shadow:0 1px 2px rgba(16,24,40,.04),0 10px 28px rgba(16,24,40,.06);--r:22px}*{box-sizing:border-box}html,body{margin:0;padding:0}body{font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:var(--ink);background:var(--bg);line-height:1.5}.orb{position:fixed;border-radius:50%;filter:blur(70px);opacity:.45;z-index:0;pointer-events:none}.orb.a{width:460px;height:460px;background:#DCE8FF;top:-160px;right:-120px}.orb.b{width:420px;height:420px;background:#EDE8FF;bottom:-160px;left:-140px}.wrap{position:relative;z-index:1;max-width:1080px;margin:0 auto;padding:48px 22px 60px}.phead{text-align:center;margin-bottom:26px}.eyebrow{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);background:#EAF1FE;padding:6px 14px;border-radius:999px}.title{font-size:clamp(28px,5vw,40px);font-weight:800;color:var(--head);margin:16px 0 6px}.subtitle{color:var(--muted);font-size:clamp(14px,2.4vw,16px);margin:0 auto;max-width:600px}.search{position:relative;max-width:520px;margin:24px auto 0}.search input{width:100%;padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:#fff;font:inherit;font-size:15px;color:var(--ink);outline:none;box-shadow:var(--shadow)}.grid{display:flex;flex-direction:column;gap:22px;margin-top:28px}.campus{background:rgba(255,255,255,.72);backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.7);box-shadow:var(--shadow);border-radius:var(--r);overflow:hidden;display:grid;grid-template-columns:300px 1fr}.cimg{position:relative;min-height:240px;background:#dbeafe}.cimg img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}.cimg-ov{position:absolute;inset:0;background:linear-gradient(180deg,rgba(11,18,32,.05),rgba(11,18,32,.78))}.cimg-tag{position:absolute;left:0;right:0;bottom:0;padding:18px;display:flex;align-items:flex-end;gap:12px}.cnum{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;font-weight:800;font-size:19px;color:#fff}.cmeta h3{margin:0;color:#fff;font-size:20px;font-weight:800}.cmeta p{margin:4px 0 0;color:rgba(255,255,255,.92);font-size:13px}.cbody{padding:22px 24px}.facs{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px 24px}.fac h4{margin:0 0 10px;font-size:12.5px;font-weight:700;text-transform:uppercase;color:var(--head);display:flex;align-items:center;gap:7px}.faci{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:#EAF1FE;color:var(--accent);flex:0 0 auto}.faci svg{width:14px;height:14px}.plist{display:flex;flex-wrap:wrap;gap:8px}.prodi{display:inline-flex;align-items:center;gap:8px;padding:7px 10px 7px 12px;background:rgba(255,255,255,.7);border:1px solid var(--line);border-radius:11px;font-size:13px;font-weight:600;color:#1F2937}.lv{font-size:10.5px;font-weight:800;padding:3px 7px;border-radius:6px;white-space:nowrap}.lv-s1{background:#EAF1FE;color:#2563EB}.lv-s2{background:#F1ECFE;color:#7C5CFC}.lv-d3{background:#FDF0DA;color:#B45309}.lv-st{background:#E3F5F1;color:#0D9488}.tint-blue{background:#2563EB}.tint-indigo{background:#4F46E5}.tint-violet{background:#7C5CFC}.tint-teal{background:#0D9488}.tint-blueb{background:#EAF1FE}.tint-indigob{background:#ECEBFE}.tint-violetb{background:#F1ECFE}.tint-tealb{background:#E3F5F1}.hide{display:none!important}.nores{display:none;text-align:center;color:var(--muted);padding:40px 20px}.nores.show{display:block}.foot{text-align:center;color:var(--faint);font-size:12.5px;margin-top:34px}@media(max-width:820px){.campus{grid-template-columns:1fr}.cimg{min-height:0;height:200px}}@media(max-width:520px){.wrap{padding:34px 16px 46px}.facs{grid-template-columns:1fr}.cimg{height:180px}}
</style></head><body>
<div class="orb a"></div><div class="orb b"></div>
<main class="wrap" id="pmb-lokasi">
  <header class="phead"><span class="eyebrow">Lokasi Perkuliahan</span><h1 class="title">Lokasi Kampus &amp; Program Studi</h1><p class="subtitle">Temukan lokasi kampus tempat perkuliahanmu berdasarkan program studi yang kamu ambil.</p><div class="search"><input id="q" type="text" placeholder="Cari program studi atau kampus..." autocomplete="off"></div></header>
  <div class="grid" id="grid">
  <?php foreach ($campuses as $index => $campus): $tone = isset($tints[$campus['color'] ?? '']) ? $tints[$campus['color']] : $tints['blue']; $image = !empty($campus['image']) ? $campus['image'] : 'https://simaba.my.id/assets/img/KAMPUS' . ($index + 1) . '.webp'; $search = strtolower(($campus['name'] ?? '') . ' ' . ($campus['address'] ?? '')); ?>
    <article class="campus" data-campus="<?php echo lokasi_h($search); ?>">
      <div class="cimg <?php echo $tone[1]; ?>"><img src="<?php echo lokasi_h($image); ?>" alt="<?php echo lokasi_h($campus['name'] ?? 'Kampus'); ?>" loading="lazy"><div class="cimg-ov"></div><div class="cimg-tag"><span class="cnum <?php echo $tone[0]; ?>"><?php echo $index + 1; ?></span><div class="cmeta"><h3><?php echo lokasi_h($campus['name'] ?? 'Kampus'); ?></h3><p><?php echo lokasi_h($campus['address'] ?? ''); ?></p></div></div></div>
      <div class="cbody"><div class="facs">
      <?php foreach (($campus['faculties'] ?? array()) as $faculty): $faculty_search = strtolower(($faculty['name'] ?? '') . ' ' . json_encode($faculty['programs'] ?? array())); ?>
        <section class="fac" data-faculty="<?php echo lokasi_h($faculty_search); ?>"><h4><span class="faci"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m22 9-10-4L2 9l10 4 10-4z"/><path d="M6 11v5c0 1 2.5 3 6 3s6-2 6-3v-5"/></svg></span><?php echo lokasi_h($faculty['name'] ?? 'Program Studi'); ?></h4><div class="plist">
          <?php foreach (($faculty['programs'] ?? array()) as $program): $pname = $program['name'] ?? ''; $level = $program['level'] ?? ''; ?><span class="prodi" data-name="<?php echo lokasi_h(strtolower($pname . ' ' . $level)); ?>"><span class="pn"><?php echo lokasi_h($pname); ?></span><span class="lv <?php echo lokasi_level_class($level); ?>"><?php echo lokasi_h($level); ?></span></span><?php endforeach; ?>
        </div></section>
      <?php endforeach; ?>
      </div></div>
    </article>
  <?php endforeach; ?>
  </div>
  <div class="nores" id="nores">Program studi atau kampus tidak ditemukan. Coba kata kunci lain.</div><p class="foot">Universitas Pamulang · Data program studi PMB</p>
</main>
<script>(function(){var q=document.getElementById('q'),cards=[].slice.call(document.querySelectorAll('.campus')),nores=document.getElementById('nores');q.addEventListener('input',function(){var s=q.value.trim().toLowerCase(),anyC=false;cards.forEach(function(c){var cm=(c.getAttribute('data-campus')||'').indexOf(s)>-1,anyP=false;[].forEach.call(c.querySelectorAll('.fac'),function(f){var fAny=false;[].forEach.call(f.querySelectorAll('.prodi'),function(p){var m=s===''||cm||(p.getAttribute('data-name')||'').indexOf(s)>-1;p.classList.toggle('hide',!m);if(m)fAny=true;});f.classList.toggle('hide',!fAny);if(fAny)anyP=true;});var show=s===''||cm||anyP;c.classList.toggle('hide',!show);if(show)anyC=true;});nores.classList.toggle('show',!anyC);});})();</script>
